describe('Form Submission Success Feedback', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should display success feedback after a valid form submission', () => {
    // Fill in form with valid data
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a test message');
    cy.get('[data-testid="submit-button"]').click();

    // Wait for API call and success response
    cy.intercept('POST', '/api/form/submit').as('formSubmit');
    cy.wait('@formSubmit').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success feedback is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');

    // Verify form is cleared
    cy.get('[data-testid="name-input"]').should('have.value', '');
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="message-textarea"]').should('have.value', '');

    // Verify success icon is visible
    cy.get('[data-testid="success-icon"]').should('be.visible');
  });

  it('should not display success feedback when form submission fails', () => {
    // Fill in form with valid data
    cy.get('[data-testid="name-input"]').type('Jane Doe');
    cy.get('[data-testid="email-input"]').type('jane@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a test message');

    // Intercept API call and simulate failure
    cy.intercept('POST', '/api/form/submit', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('formSubmitFailure');

    cy.get('[data-testid="submit-button"]').click();

    // Wait for failed API call
    cy.wait('@formSubmitFailure');

    // Verify success feedback is NOT displayed
    cy.get('[data-testid="success-message"]').should('not.exist');
    cy.get('[data-testid="success-icon"]').should('not.exist');

    // Verify error feedback is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to submit form');

    // Verify form data is retained on error
    cy.get('[data-testid="name-input"]').should('have.value', 'Jane Doe');
    cy.get('[data-testid="email-input"]').should('have.value', 'jane@example.com');
  });
});
